import{_ as o,o as a,c as t,a4 as d}from"./chunks/framework.cdJ1L9ZC.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog","order":1,"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"en/changelog.md","lastUpdated":null}'),n={name:"changelog.md"};function c(i,e,s,r,l,h){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Charts.</strong> Five components on one engine: <code>Sparkline</code>, <code>LineChart</code>, <code>AreaChart</code>, <code>BarChart</code> and <code>PieChart</code>. They take their data the way <code>Table</code> does — <code>series</code> (or, for a pie, <code>data</code>) as a prop rather than markup — and they take it in the <em>same</em> shape as each other, so a dashboard tile can be switched from one chart to another without rewriting what feeds it. <code>Statistic</code> joins them in a new <strong>Charts</strong> group in the docs.</li><li><strong>A <code>null</code> is a gap, not a zero,</strong> on every one of them. A line breaks at it, an area breaks with it, a bar is not drawn and the table cell is empty; <code>connectNulls</code> bridges it for the case where the gap is an artefact of collection rather than a month in which nothing happened. A chart that renders missing data as zero reports an outage as a collapse.</li><li><strong>A series&#39; colour follows its place in the array it was passed, never its position among the visible ones</strong> — so filtering a legend cannot repaint the survivors, and a reader who learned that Europe is blue keeps that. <code>series.color</code> overrides the slot with a <code>NebaColor</code> family or any CSS colour, and a point&#39;s own <code>color</code> overrides that for one mark.</li><li><code>LineChart</code> takes <code>curve</code> (<code>linear</code>, a monotone <code>smooth</code> that will not dip below a value both its neighbours are above, or <code>step</code>), <code>markers</code>, <code>gradient</code>, <code>connectNulls</code>, <code>valueLabels</code> and <code>stacked</code>. Its value axis crops to the data, because a line encodes a <em>position</em> and cropping moves every point by the same amount.</li><li><code>AreaChart</code> takes the same three curves plus <code>stacked</code> — <code>true</code> for totals, <code>&#39;full&#39;</code> for a chart about the mix rather than the size, where the axis becomes a percentage and the tooltip and the table keep the caller&#39;s own number. Its axis keeps zero, because there the fill&#39;s thickness <em>is</em> the magnitude. Unstacked bands are a wash that fades downward so two of them overlapping stay readable; stacked bands are a flat tint parted by two pixels of the surface rather than by a stroke.</li><li><code>BarChart</code> takes <code>orientation</code> — <code>horizontal</code> is the right answer whenever the category names are words — plus <code>stacked</code> (<code>true</code> / <code>&#39;full&#39;</code>), <code>rounded</code>, <code>barSize</code> and <code>valueLabels</code>. Corners are cut off the <strong>data end</strong> only; a rounded foot makes the axis look scalloped. Bars grow from where zero is rather than from the bottom of the plot, so a negative bar starts on the same line as its neighbours.</li><li><code>PieChart</code> takes <code>shape</code> — <code>pie</code>, <code>donut</code> or a <code>semi</code> circle — plus <code>center</code> for what goes in the hole, and <code>valueLabels</code> for each slice&#39;s share, drawn only where the text fits with room on both sides and dropped rather than clipped where it does not.</li><li><code>Sparkline</code> is not a small chart: no axes, no grid, no legend, and no numbers, because every number it could label is one the sentence around it already has. <code>shape</code> is a line, an area or bars; <code>endDot</code>, <code>baseline</code>, <code>min</code> and <code>max</code> are the rest of it. It fills itself with its own range, which is what makes it legible at twenty pixels tall — and why two of them are only comparable when both are given the same <code>min</code> and <code>max</code>.</li><li><strong>A hidden table under every chart, always.</strong> The drawing is <code>aria-hidden</code> and the data is rendered as a visually clipped <code>&lt;table&gt;</code> captioned with <code>label</code>, so no value is reachable only by pointer. The plot itself is focusable: <code>←</code>/<code>→</code> step the crosshair between categories, <code>Home</code>/<code>End</code> jump to the ends, <code>Escape</code> clears it, and the tooltip is a live region. The legend is a list of <code>aria-pressed</code> buttons, so which series are drawn is stated rather than implied by colour.</li><li><strong>Eight new colour tokens, <code>--neba-chart-1</code> … <code>--neba-chart-8</code>, per theme</strong> — and the one place in the library where a colour is not a semantic role, because a series is an <em>entity</em> and nothing about it means success or danger. They were solved rather than picked: every step inside the OKLCH lightness band, chroma above the floor where a hue stops carrying identity, every adjacent pair at least ΔE 8 apart in OKLab under simulated protanopia and deuteranopia (measured at 13.6 light and 14.5 dark), and every slot above 4:1 on white and 5.3:1 on the dark sheet. Dark is re-solved against the dark surface rather than lightened from the light values. Slots are handed out in order and never cycled: a ninth series is an &quot;Other&quot; row or a second chart, not a ninth hue.</li><li><code>--neba-chart-grid</code>, <code>--neba-chart-axis</code>, <code>--neba-chart-baseline</code> and <code>--neba-chart-gap</code> — the chart&#39;s chrome, derived from <code>--neba-border</code> and <code>--neba-surface</code> so a chart&#39;s rules and a Card&#39;s dividers are one family of line. Gridlines are solid hairlines: a dashed grid says &quot;projection&quot; when all it is is a grid.</li><li><code>src/types.ts</code> gains the vocabulary the charts share — <code>NebaChartSeries</code>, <code>NebaChartDatum</code>, <code>NebaChartPoint</code>, <code>NebaChartCategory</code>, <code>NebaChartAxis</code>, <code>NebaChartLegend</code>, <code>NebaChartTooltip</code>, <code>NebaChartCurve</code>, <code>NebaChartValueLabels</code> — for the reason <code>NebaSize</code> is there: a <code>series</code> handed to a LineChart has to be the one a BarChart takes.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Five component pages in both locales — <code>Sparkline</code>, <code>LineChart</code>, <code>AreaChart</code>, <code>BarChart</code>, <code>PieChart</code> — with the data model written out once on the LineChart page and cross-referenced from the rest, their props rows (including tables for <code>NebaChartAxis</code>, <code>NebaChartLegend</code> and <code>NebaChartTooltip</code>), sixteen demos, a <strong>Charts</strong> group in the component gallery, three charts and a row of sparklines on the sample screen, and their entries in <code>llms.txt</code>.</li><li><code>Statistic</code> moved from <strong>Display</strong> to <strong>Charts</strong>, in both locales and in every index that names it.</li></ul><h2 id="_1-4-0-2026-08-06" tabindex="-1">1.4.0 (2026-08-06) <a class="header-anchor" href="#_1-4-0-2026-08-06" aria-label="Permalink to &quot;1.4.0 (2026-08-06)&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>Empty</code> — what stands where content would have been, in four slots: <code>icon</code>, <code>title</code>, <code>children</code> and <code>action</code>. It is the other half of <code>Skeleton</code>: one is the shape of something on its way, the other is the shape of something that is not coming, and a list showing neither has a blank rectangle where its answer should be.</li><li><strong>The headline is defaulted rather than required</strong>, because the version that says nothing useful is the version that gets shipped. <code>title</code> falls back to the <code>locale</code>&#39;s way of saying that there is nothing here — a new <code>empty</code> namespace in the message table, translated into all eighteen languages the library already speaks — and <code>title={false}</code> drops it for a state that is a glyph and a sentence. <code>icon</code> defaults to an empty tray and takes any node, so an illustration or another set&#39;s glyph goes in without a wrapper; <code>action</code> holds the way out, and several of them wrap together in one row.</li><li><code>variant</code> defaults to <code>text</code> on this component and on no other: an empty state is nearly always already inside a Card, a Table or a panel, and a second rectangle inside the first is one rectangle too many. <code>outline</code> and <code>solid</code> are the undyed container sheet, so <code>color</code> reaches the hairline and the ring and stops — an empty state arriving in the accent colour is making a claim about content that does not exist. The root is a <code>role=&quot;status&quot;</code> live region, which is what lets a list that empties under the reader say so; <code>role={undefined}</code> turns that off for a state that is part of the page on arrival.</li><li><code>Mockup</code> — a device with a screen you can put anything on. <code>device</code> is the one prop with no default and picks the machine: a <code>mobile</code>, a <code>tablet</code>, or a <code>desktop</code> that is either a <code>monitor</code> on a stand or a <code>laptop</code> on a base. <code>os</code> draws that system&#39;s own chrome — a menu bar and a floating dock, a centred taskbar, a top bar with a dock down the leading edge, a status bar with a home indicator or three navigation glyphs — and <code>systemUi={false}</code> takes all of it away. <code>bezel</code> runs from <code>none</code> (no hardware at all, just the glass) through <code>thin</code> and <code>standard</code> to <code>thick</code>, which is an older device with a forehead and a chin rather than a wider frame; <code>finish</code> is <code>graphite</code>, <code>silver</code> or <code>white</code>; <code>notch</code> is a <code>dynamic-island</code>, a <code>notch</code>, a <code>punch-hole</code> or <code>none</code>, defaulting to whatever the device would really have. <code>orientation</code> turns a handheld, and the screen, the bezel and the cut-out turn with it.</li><li><strong>The screen is a viewport at the device&#39;s real resolution, not a picture scaled down.</strong> <code>size</code> is a five-step ladder of genuine resolutions per device — a phone from 320 to 430 CSS pixels wide, a desktop from 1024 to 1920 — and <code>resolution</code> takes a <code>{ width, height }</code> pair for anything else. The whole device is then scaled once to whatever <code>width</code>/<code>height</code> come to on the page, so the same component laid out inside a phone and inside a desktop wraps differently in each. The screen is also a container named <code>neba-screen</code>, so content can answer to the device with a container query rather than to the window.</li><li><code>scroll</code> lets content taller than the screen scroll instead of being clipped; <code>wallpaper</code> takes any CSS <code>background</code> for what sits behind it; <code>time</code> is the clock, and the only text the chrome draws — every menu title, dock icon and tray glyph is an abstract shape, so there is nothing to translate and no other party&#39;s marks in the library. Every part of the device is <code>aria-hidden</code>, which leaves a screen reader with <code>children</code> and nothing else.</li><li><code>DataTable</code> — a table for a lot of rows. <code>Table</code> draws a grid; this one is a place to work, and it takes the same two props to get there: <code>headers</code> and <code>items</code>. It is compact by default (<code>sm</code>, <code>compact</code>) with its own row ladder a step below the rest of the library, <code>striped</code> takes <code>true</code>, <code>&#39;odd&#39;</code> or <code>&#39;even&#39;</code>, and the parity is counted over the whole set so it does not change as the rows are scrolled or sorted.</li><li><strong>Only the rows on screen are in the DOM, and <code>height</code> is what turns that on.</strong> Every row is <code>rowHeight</code> tall — defaulted off the <code>size</code>/<code>density</code> ladder — so the offset of a row is its index times a constant and nothing has to be measured on a scroll frame; the rows that are left out stand up as two spacer rows, which is what keeps the scrollbar honest. Without a <code>height</code> or a <code>maxHeight</code> there is nothing to measure against and every row is rendered, whatever <code>virtual</code> says; <code>virtual={false}</code> asks for that on purpose, for a table small enough that find-in-page matters more than the DOM count. Cells truncate rather than wrap, which is the price of the arithmetic.</li><li><strong>Selecting is the file manager&#39;s, not the form&#39;s.</strong> A click chooses a row and drops the rest, <kbd>Ctrl</kbd>/<kbd>⌘</kbd> adds one, <kbd>Shift</kbd> takes the run between, a drag takes the run under the pointer and scrolls when it reaches an edge, and the arrow keys do all three with the same modifiers — plus <kbd>Home</kbd>, <kbd>End</kbd>, <kbd>PageUp</kbd>, <kbd>PageDown</kbd>, <kbd>Space</kbd>, <kbd>Ctrl</kbd>+<kbd>A</kbd>, <kbd>Esc</kbd> and <kbd>Enter</kbd>. <code>selectionMode</code> is <code>none</code>, <code>single</code> or <code>multiple</code>; <code>checkboxes</code> adds a tick column and is deliberately not the default, because a column of checkboxes says the task is choosing and on most tables it is not. With a selection mode the table is a <code>grid</code> with one tab stop and <code>aria-activedescendant</code>, since a virtual row cannot hold the focus.</li><li><code>sortable</code> makes the headings pressable and they cycle ascending → descending → <strong>unsorted</strong>, because the order the rows arrived in is a state nothing else can get back to. <code>sortMode=&quot;multiple&quot;</code> lets a Shift-click add a second key rather than replace the first. <code>resizable</code> puts a handle on each boundary; the first drag freezes every column at the width the browser had given it, so pulling one moves one, and a double-click restores it. Adjacent columns sharing a <code>group</code> string merge under one heading in a second header row.</li><li><code>paging=&quot;pages&quot;</code> swaps the scroll for a footer holding the range, the number of chosen rows, a page-size <code>Select</code> and a <code>Pagination</code>; <code>footer</code> shows that bar on its own, so a scrolling table can have the count without the pages. <code>search</code> matches every column that has not set <code>searchable: false</code>, case- and accent-insensitively, and <code>searchable</code> draws the field with <code>toolbar</code> filling the rest of its bar. <code>manual</code> hands any of <code>&#39;sort&#39;</code>, <code>&#39;filter&#39;</code> and <code>&#39;pages&#39;</code> back to the caller — with <code>rowCount</code> for the total — so a table whose rows come from a server is the same component rather than a second one.</li><li>The i18n table gains a <code>table</code> namespace — the search field&#39;s placeholder, the two ticks&#39; labels, the page-size label, and the footer&#39;s count and selection sentences — in all eighteen languages. The two that carry numbers are whole templates with <code>{start}</code>, <code>{end}</code>, <code>{total}</code> and <code>{count}</code> in them rather than fragments, because what differs between languages is the order the numbers appear in.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Forcing a theme on a nested element now works in both directions.</strong> <code>.dark</code> / <code>[data-theme=&#39;dark&#39;]</code> on an element that is not the document root was already documented, but the light values were declared on <code>:root</code> alone, so <code>.light</code> / <code>[data-theme=&#39;light&#39;]</code> inside a dark page had nothing to switch back to. The light block now carries all three selectors.</li><li><code>--neba-plate-solid</code>, <code>--neba-plate-glass</code> and the <code>--neba-shadow-1</code> … <code>--neba-shadow-4</code> ladder moved into the derived block. Each is a base token spread into a shadow list, and declared only on <code>:root</code> they froze to the light hairline and the light ambient inside any theme root that was not the document root.</li></ul><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Every live preview carries a theme switch in its top corner, so a component can be read in the theme the page is not in without taking the whole site with it. Untouched previews still follow the site switch, and a preview flipped back to the page&#39;s own theme rejoins it.</li><li>An <code>Empty</code> page in both locales with eight examples, its props rows, its demos, a card in the component gallery, a place on the sample screen beside the placeholder it is the other half of, and its entry in <code>llms.txt</code>.</li><li>A <code>Mockup</code> page in both locales with eleven examples, its props rows, its demos, a card in the component gallery, a place on the sample screen and its entry in <code>llms.txt</code>.</li><li>A <code>DataTable</code> page in both locales with seven examples, two props tables, its demos, a card in the component gallery, twelve thousand rows on the sample screen and its entry in <code>llms.txt</code>.</li><li><strong>The nav bar and the sidebar no longer hang off the edges between 1440px and 1600px.</strong> The site raises <code>--vp-layout-max-width</code> to 1600px, and the default theme centres the shell on the article by taking half of what the page has left over — an expression it writes out five times without a floor, because at its own 1440px it cannot come out below zero. At ours it can: the social icons sat 8px outside the viewport and the sidebar climbed over the article&#39;s left margin. All five now read one floored <code>--neba-gutter</code>, which reduces every one of them to the gutter plus nothing, the page margin, or the sidebar&#39;s width.</li><li><code>npm run docs:dev</code> starts in about four seconds instead of fourteen. All three <code>docs:*</code> scripts ran <code>npm run build</code> first — ten seconds of <code>format:fix</code>, <code>tsc</code> and terser that nothing then looked at, since the docs resolve <code>neba</code> to <code>src/index.ts</code> and import <code>src/styles.css</code> directly. Prettier now runs where it always did as part of <code>npm run build</code>, and CI still checks it.</li></ul><h2 id="_1-3-0-2026-08-05" tabindex="-1">1.3.0 (2026-08-05) <a class="header-anchor" href="#_1-3-0-2026-08-05" aria-label="Permalink to &quot;1.3.0 (2026-08-05)&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>A sixth group, Transitions: eleven <code>Animate*</code> wrappers that make anything move.</strong> <code>AnimateFade</code>, <code>AnimateGrow</code>, <code>AnimateZoom</code>, <code>AnimateSlide</code>, <code>AnimateRotate</code> and <code>AnimateBlink</code> are the six named effects; <code>AnimateAppear</code>, <code>AnimateTyping</code>, <code>AnimateLighting</code>, <code>AnimateMarquee</code> and <code>AnimateHeadline</code> are the five that have to understand what their children are. All eleven take the same settings — <code>duration</code> and <code>delay</code> in milliseconds, <code>easing</code>, <code>repeat</code> (a count or <code>&#39;infinite&#39;</code>), <code>alternate</code>, <code>paused</code>, and <code>trigger</code>: <code>mount</code>, <code>visible</code> (with <code>once</code> and <code>threshold</code>), <code>hover</code>, or <code>manual</code> driven by <code>play</code>. Every one of them is switched off entirely by a <code>prefers-reduced-motion</code> preference, so none of them is ever the only thing carrying a message.</li><li><strong>A <code>transition</code> prop on the components that display something</strong> — <code>Box</code>, <code>Card</code>, <code>Statistic</code>, <code>Alert</code>, <code>Chip</code>, <code>Avatar</code>, <code>Icon</code>, <code>Typography</code> and <code>Blockquote</code>. <code>transition=&quot;fade&quot;</code> is an entrance run once on mount, and the object form takes the details: <code>{ type: &#39;slide&#39;, from: &#39;left&#39;, duration: 500 }</code>. It is offered on no component that is pressed, because a control that moves under the pointer aiming at it is the one thing the design language rules out. Anything past a mount — a replay, a scroll trigger, a hover — is an <code>Animate*</code> component, and any component can be wrapped in one.</li><li><code>ColorPicker</code> — a colour chosen by eye: a saturation square, a hue rail, an optional opacity rail, a field for typing a value in, and a grid of swatches. <code>format</code> decides whether the value comes back as hex, <code>rgb()</code> or <code>hsl()</code>; <code>alpha</code> adds the fourth channel; <code>swatches</code> replaces the built-in set with the colours a product actually uses; <code>inline</code> draws the panel into the page instead of into a popup. It reads hex in all four lengths, <code>rgb()</code>/<code>rgba()</code> and <code>hsl()</code>/<code>hsla()</code> in both syntaxes, and it adds no dependency — the conversions are a hundred lines of arithmetic in <code>internal/color.ts</code>.</li><li>The i18n table gains a <code>color</code> namespace, so the picker&#39;s square, rails, field and swatch grid — none of which have any text on them — are named in all nineteen languages. <code>locale</code> picks the language and <code>labels</code> overrides any one of them.</li></ul><h3 id="documentation-2" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-2" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Pages for <code>ColorPicker</code> and the eleven <code>Animate*</code> components in both locales, their props rows, their demos, cards in the component gallery, a place on the sample screen, and their entries in <code>llms.txt</code>.</li><li><strong>Prop conventions gains a Motion section</strong>, which is where the shared animation vocabulary and the rule about which components take <code>transition</code> are written down.</li></ul><h2 id="_1-2-0-2026-08-01" tabindex="-1">1.2.0 (2026-08-01) <a class="header-anchor" href="#_1-2-0-2026-08-01" aria-label="Permalink to &quot;1.2.0 (2026-08-01)&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Eight components, bringing the library to fifty-seven: <code>Avatar</code>, <code>Breadcrumb</code> (with <code>BreadcrumbItem</code>), <code>ChatBubble</code>, <code>OtpField</code>, <code>Panes</code> (with <code>Pane</code>), <code>Spoiler</code>, <code>TextLink</code> and <code>TreeView</code> (with <code>TreeItem</code>). <code>Panes</code> opens a fifth group, <strong>Layout</strong>, alongside <code>Container</code> and <code>Grid</code>.</li><li><strong>The library speaks nineteen languages on its own behalf.</strong> Almost nothing in Neba writes text a reader sees — a Button says whatever it was handed — but a few components have to invent a string because there is nowhere else for it to come from: the sentence read out after a link that opens a new tab, the label on the button that uncovers a <code>Spoiler</code>, the word under a chat message that says it was read. Those are now one table rather than eight English defaults. <code>TextLink</code>, <code>Spoiler</code> and <code>ChatBubble</code> take a <code>locale</code>, and every string still has an override prop of its own, so an unsupported language is never a dead end. A tag resolves by script, then by region, then by language (<code>zh-Hant-TW</code> → <code>zh-hant</code>, <code>pt-BR</code> → <code>pt</code>), and a translation that fills in part of the table falls back to English one namespace at a time rather than leaving blanks.</li><li><code>Avatar</code> — an image that falls back to initials, to a glyph, or to a silhouette, so the slot is never an empty box. <code>shape</code> is <code>circle</code> or <code>square</code>, <code>delay</code> holds the fallback back long enough for a cached image not to flash it, and <code>onLoadingStatusChange</code> reports <code>idle</code> / <code>loading</code> / <code>loaded</code> / <code>error</code>.</li><li><code>Breadcrumb</code> — a trail that collapses in the middle when it is too long: <code>maxItems</code>, <code>itemsBeforeCollapse</code> and <code>itemsAfterCollapse</code> decide where, and <code>expandable</code> makes the ellipsis a button that opens the rest in place. <code>separator</code> takes <code>chevron</code>, <code>arrow</code>, <code>slash</code>, <code>dot</code> or a node of your own.</li><li><code>ChatBubble</code> — one message in a conversation. The avatar, the name, the time, the delivery mark, the media and the link card are each drawn only when given something, so the same component is a bare bubble or a full row. <code>status</code> runs <code>sending</code> → <code>sent</code> → <code>delivered</code> → <code>read</code>, plus <code>failed</code>; <code>typing</code> draws three dots that change colour rather than bounce.</li><li><code>OtpField</code> — a one-time code as one field per character. <code>length</code>, <code>charset</code> (<code>numeric</code>, <code>alpha</code>, <code>alphanumeric</code>, <code>any</code>), <code>mask</code>, and <code>groupSize</code> with a <code>separator</code> for codes written in blocks. <code>onComplete</code> fires when the last box is filled, <code>autoSubmit</code> submits the form it is in, and <code>onValueInvalid</code> reports what was rejected.</li><li><code>Panes</code> — regions with a draggable bar between each pair, horizontal or vertical. Each <code>Pane</code> takes <code>defaultSize</code>, <code>minSize</code> and <code>maxSize</code> as a number of pixels or any CSS length; <code>resizable</code> turns the bars off, and <code>onResize</code> / <code>onResizeEnd</code> report the split.</li><li><code>Spoiler</code> — content covered by a blur rather than removed, so a reader can see that something is there without reading it by accident. Controlled with <code>revealed</code> / <code>defaultRevealed</code> / <code>onRevealedChange</code>; <code>reversible</code> allows covering it again, <code>maxHeight</code> clamps it to a fade-out instead, and <code>blur</code> is the radius.</li><li><code>TextLink</code> — a link with no surface of its own. <code>underline</code> is <code>always</code>, <code>hover</code> or <code>none</code>, <code>newTab</code> adds the mark and the sentence a screen reader needs, <code>icon</code> overrides or drops that mark, and <code>render</code> swaps in a router&#39;s own link component.</li><li><code>TreeView</code> — a tree with roving focus, controlled <code>expanded</code> and <code>selected</code>, and <code>multiple</code> for checkbox-style selection. <code>lines</code> draws the guides as <code>none</code>, <code>simple</code> or <code>folder</code> — the rail runs past an expanded subtree to the next sibling and stops halfway down the last child, the way a file manager draws it, and mirrors under RTL without a second rule.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>The Examples section is four pages, not one.</strong> <code>/examples/</code> no longer resolves to a page — the overview moved to <a href="https://neba.cdget.com/examples/overview" target="_blank" rel="noreferrer"><code>/examples/overview</code></a> and three concept screens joined it. Any link you have to <code>/examples/</code> needs updating.</li><li>The stylesheet carries a <code>.neba-link</code> rule, written as <code>.neba-link.neba-link</code> so that a host&#39;s <code>.prose a</code> or <code>.vp-doc a</code> cannot outrank the link&#39;s underline thickness, offset and colour. Like <code>neba-portal</code>, the class is a hook you can exempt from your own typography rules.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The date formatter cache joined a locale and its options with a space, which is a character both halves of the key can contain. Two different requests could land on one entry and the second would be formatted with the first&#39;s options. The separator is now one that cannot appear in either.</li></ul><h3 id="documentation-3" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-3" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li><strong>Three concept screens</strong>, each a whole fictional product page built only out of the library: a <a href="https://neba.cdget.com/examples/concept-landing" target="_blank" rel="noreferrer">landing page</a>, an <a href="https://neba.cdget.com/examples/concept-dashboard" target="_blank" rel="noreferrer">admin dashboard</a> and a <a href="https://neba.cdget.com/examples/concept-signup" target="_blank" rel="noreferrer">sign-up flow</a>.</li><li>The home page now says what the library is rather than how it is drawn — what ships, what is tested, and what an install actually gets you.</li><li><strong>Every page carries its own description.</strong> A page&#39;s lede is read out of the source and becomes its <code>&lt;meta name=&quot;description&quot;&gt;</code>, so pages no longer share one sentence between them. Canonical URLs, an <code>hreflang</code> pair per locale with an <code>x-default</code>, Open Graph and Twitter cards, JSON-LD on the home page, and a <code>robots.txt</code> naming the sitemap are generated in the build.</li><li><strong>A preview mounts when it is scrolled into view</strong>, not when the page loads. A component page holds a dozen of them, and mounting all at once put the one being read behind chunks for previews far below the fold. The empty box reserves its height before and after, so nothing jumps.</li><li>New icons and social image at 128 and 256 px, an <code>apple-touch-icon</code>, and a <code>theme-color</code>.</li><li>Pages for the eight new components in both locales, their props rows, their demos, and their entries in <code>llms.txt</code>.</li></ul><h2 id="_1-1-0-2026-07-29" tabindex="-1">1.1.0 (2026-07-29) <a class="header-anchor" href="#_1-1-0-2026-07-29" aria-label="Permalink to &quot;1.1.0 (2026-07-29)&quot;">​</a></h2><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><ul><li><p><strong><code>neba/styles.css</code> now ships compiled.</strong> It carries the design tokens, the real rules for every utility class the components use, and a small reset — so the whole setup is <code>npm install neba</code> and one <code>@import</code>. Tailwind is no longer a requirement on your side; it builds this package and stays a devDependency of it. About 13 kB gzipped.</p></li><li><p><strong>New export: <code>neba/tailwind.css</code>.</strong> The token sheet, for a project that already runs Tailwind v4 — it registers the package as a Tailwind source, so your own build generates the components&#39; utilities in the same pass as your app&#39;s and a <code>className</code> you pass to a component sorts correctly against the component&#39;s own classes. If you were on the previous two-line setup, this is the line to switch to:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tailwindcss&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;neba/tailwind.css&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* was: neba/styles.css */</span></span></code></pre></div></li><li><p><strong>The bundled reset</strong> is Tailwind&#39;s Preflight cut down to what the components actually need — <code>box-sizing</code>, font inheritance on form controls, list markers off. It does not touch the typography of your paragraphs, headings or links, and every rule is wrapped in <code>:where()</code>, so a single type selector of your own beats it whatever the import order. It is in <code>neba/styles.css</code> only; the Tailwind path has Preflight already.</p></li><li><p><strong><code>react</code> and <code>react-dom</code> are now declared as <code>peerDependencies</code></strong> (<code>^18.0.0 || ^19.0.0</code>) rather than only as devDependencies, so the requirement is stated where a package manager can check it. <code>@types/react</code> is an optional peer for TypeScript consumers.</p></li></ul><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Eighteen components: <code>Blockquote</code>, <code>Carousel</code>, <code>Container</code>, <code>DatePicker</code>, <code>DateRangePicker</code>, <code>DateTimePicker</code>, <code>Grid</code>, <code>GridContainer</code>, <code>Highlight</code>, <code>Icon</code>, <code>IconButton</code>, <code>Pill</code>, <code>SegmentedButton</code> (with <code>Segment</code>), <code>Shortcut</code>, <code>Statistic</code>, <code>TimePicker</code>, <code>Timeline</code> (with <code>TimelineItem</code>) and <code>Toolbar</code>.</li><li>Shared types for the new layout and date work: <code>NebaPosition</code>, <code>NebaBreakpoint</code>, <code>NebaResponsive&lt;T&gt;</code>, <code>NebaWeekday</code>, <code>NebaJustifyContent</code>, <code>NebaAlignItems</code> and <code>NebaAlignSelf</code>.</li><li><code>Divider</code> takes a <code>thickness</code>, as a number of pixels or any CSS length.</li><li><code>Pill</code> takes <code>elevation</code>, <code>startIcon</code> / <code>endIcon</code>, <code>title</code> / <code>description</code> / <code>details</code>, <code>expanded</code> and <code>position</code>.</li><li><code>llms.txt</code>, for agents reading the documentation site.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>Select</code>, <code>DatePicker</code> and <code>DateRangePicker</code> hold their trigger at the width of the longest thing it could say. Choosing a shorter option no longer shrinks the field out from under the pointer that just used it.</li><li><code>Checkbox</code> and <code>RadioGroup</code> drop the white plate highlight. A 1px hairline is light on a cut edge at 32px and a bevel at 18px; the acrylic surface stays, only the highlight goes.</li><li>A highlighted row in a <code>Select</code> or <code>Combobox</code> popup now takes the accent text colour as well as the soft background.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>Select</code> and <code>Combobox</code> popups render through a portal, outside the element their <code>--n-*</code> slots were declared on, which left every <code>var()</code> in them with nothing to resolve to: a <code>currentColor</code> hairline instead of the family&#39;s, a transparent surface, and a highlighted row that did not light at all. The slots are now set on the popup itself.</li><li>A field at the top or bottom of a scrolling <code>Dialog</code> body had its focus ring sliced off by the scroll container. The body without <code>dividers</code> now reserves the 4px the ring is drawn in and gives the space straight back, so nothing on the sheet moves.</li><li><code>Pagination</code> keyed its buttons by page number, so recentring the window moved the DOM nodes and the button under the pointer became a different element — its hover bloom faded out while a fresh neighbour&#39;s faded in from a centre it had no pointer position for. The row is keyed by slot now.</li><li><code>Combobox</code>&#39;s input stretches to the height of the row it sits on rather than to a fixed <code>1lh</code>, which put the placeholder a pixel or two above the chips beside it.</li></ul><h3 id="documentation-4" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-4" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>The sidebar is four sections — Guide, Components, Design and Discover more — with the component groups kept as headings inside Components, and the index page as an entry of its own rather than as the heading&#39;s link.</li><li>The design pages moved from <code>guide/</code> to <code>design/</code>.</li><li>This changelog is published at <a href="https://neba.cdget.com/changelog" target="_blank" rel="noreferrer">/changelog</a> in both locales.</li></ul><h2 id="_1-0-0-2026-07-26" tabindex="-1">1.0.0 (2026-07-26) <a class="header-anchor" href="#_1-0-0-2026-07-26" aria-label="Permalink to &quot;1.0.0 (2026-07-26)&quot;">​</a></h2><ul><li>First release</li></ul><h2 id="_0-0-1-2025-12-08-alpha" tabindex="-1">0.0.1 (2025-12-08 / Alpha) <a class="header-anchor" href="#_0-0-1-2025-12-08-alpha" aria-label="Permalink to &quot;0.0.1 (2025-12-08 / Alpha)&quot;">​</a></h2><ul><li>Alpha release (Not tested. Do not use production.)</li></ul>`,42)])])}const g=o(n,[["render",c]]);export{u as __pageData,g as default};
